import assert from 'node:assert/strict';
import {randomUUID,createHash} from 'node:crypto';
import {readFileSync,writeFileSync} from 'node:fs';
import {pathToFileURL} from 'node:url';
const root=process.cwd(),inputPath=process.argv[2];
const captured=JSON.parse(readFileSync(inputPath,'utf8'));
const {withDisposablePostgres}=await import(pathToFileURL(root+'/scripts/helpers/disposable-postgres.mjs'));
const {preparePhase3Database,as,json,literal}=await import(pathToFileURL(root+'/scripts/helpers/v2-phase3-fixture.mjs'));
const report={scope:'Actual browser-generated template request replayed through actual database routines in disposable PostgreSQL; synthetic Auth/Storage and fixture grant. Browser server I/O remained mocked.',checks:[],capturedRequest:captured,capturedRequestSha256:createHash('sha256').update(readFileSync(inputPath)).digest('hex'),status:'running'};
const check=(id,fn)=>{fn();report.checks.push({id,status:'pass'});console.log('PASS '+id)};
try{await withDisposablePostgres(async db=>{
 const f=preparePhase3Database(db),{query,rejects}=db;
 for(const m of ['20261113090000_add_v2_sales_catalogue.sql','20261113100000_add_v2_checkout_ledger.sql','20261113110000_add_v2_payment_fulfillment.sql'])db.apply(m);
 const rpc=(id,name,args='')=>JSON.parse(query(as(id,`select public.${name}(${args})`))||'null');
 const s=randomUUID(),batch=randomUUID();query(`insert into auth.users(id,email) values('${s}','synthetic-student@example.invalid');update public.profiles set role='student',is_active=true where id='${s}'`);
 const quote=JSON.parse(query("select public.quote_v2_products(array['quant_crash'])"));query(`select public.grant_v2_purchase('${s}',array['quant_crash'],'synthetic-access',now()-interval '1 second','${quote.price_version_id}',${quote.amount_paise},'INR')`);
 check('browser-generated-class-and-session-identities-are-distinct',()=>{assert.equal(captured.document.sessions.length,2);assert.equal(new Set([...captured.document.sessions,...captured.document.events].map(x=>x.key)).size,4);assert.equal(captured.document.events[0].title,captured.document.events[1].title)});
 const saveArgs=`'${captured.id}','${captured.productCode}',${captured.expectedRevision},'${captured.requestId}',${json(captured.document)}`;
 check('actual-browser-template-saves-and-replays-without-duplicate',()=>{rpc(f.admin,'save_v2_template_draft',saveArgs);rpc(f.admin,'save_v2_template_draft',saveArgs);assert.equal(query(`select count(*) from public.v2_course_template_revisions where template_id='${captured.id}'`),'1')});
 const input={id:batch,templateId:captured.id,templateRevision:1,expectedRevision:0,requestId:randomUUID(),title:captured.document.title,startDate:'2026-12-10',timeZone:'Asia/Kolkata',events:null};
 let preview=rpc(f.admin,'preview_v2_batch_draft',json(input));const saved=rpc(f.admin,'save_v2_batch_draft',`${json(input)},${literal(preview.fingerprint)}`);
 rpc(f.admin,'set_v2_batch_enrollment',`'${batch}','${s}',true,0`);
 const course=()=>rpc(s,'get_my_v2_published_course',`'${batch}'`),state=()=>rpc(s,'get_my_v2_learning_state',`'${batch}'`);
 check('generated-course-draft-stays-private-and-unmapped',()=>{assert.equal(course(),null);assert.equal(query(`select count(*) from public.v2_live_session_mappings where batch_id='${batch}'`),'0')});
 const kinds=['preSessionReads','recordings','postSessionReads','materials'];
 const sessions=captured.document.sessions.map((session,index)=>({...session,content:index?session.content:Object.fromEntries(kinds.map(kind=>[kind,[{key:randomUUID(),title:`Synthetic ${kind}`,url:`https://example.test/${kind}`}]]))}));
 const edited={...input,expectedRevision:1,requestId:randomUUID(),sessions,events:saved.draft.events.map(({key,kind,localDate,localStartTime,durationMinutes,instructor,capacity})=>({key,kind,localDate,localStartTime,durationMinutes,instructor,capacity}))};
 preview=rpc(f.admin,'preview_v2_batch_draft',json(edited));rpc(f.admin,'save_v2_batch_draft',`${json(edited)},${literal(preview.fingerprint)}`);
 check('four-resource-types-save-in-private-draft-before-publication',()=>assert.equal(course(),null));
 const publication={batchId:batch,batchRevision:2,expectedRevision:0,requestId:randomUUID(),action:'publish'};
 preview=rpc(f.admin,'preview_v2_batch_publication',json(publication));rpc(f.admin,'save_v2_batch_publication',`${json(publication)},${literal(preview.fingerprint)}`);
 check('single-publication-delivers-prepared-sessions-and-resources',()=>{assert.equal(course().sessions.length,2);for(const kind of kinds)assert.equal(course().sessions[0].content[kind][0].url,`https://example.test/${kind}`)});
 rpc(f.admin,'set_v2_live_registration',`'${batch}','${s}',true,0`);
 check('completion-still-requires-explicit-mapping',()=>rejects(as(f.admin,`select public.complete_v2_learning_live_class('${batch}','${captured.document.events[0].key}',1)`),/mapping is required/));
 for(let i=0;i<2;i++)rpc(f.admin,'set_v2_live_session_mapping',`'${batch}','${captured.document.events[i].key}','${sessions[i].key}',1`);
 check('same-title-classes-retain-two-explicit-session-mappings',()=>{const rows=rpc(f.admin,'list_v2_live_session_mappings',`'${batch}'`);assert.equal(rows.length,2);assert.equal(new Set(rows.map(x=>x.sessionKey)).size,2)});
 for(const event of captured.document.events)rpc(f.admin,'complete_v2_learning_live_class',`'${batch}','${event.key}',1`);
 check('both-classes-complete-with-distinct-feedback-obligations',()=>{assert.equal(query(`select count(*) from public.v2_live_class_completions where batch_id='${batch}'`),'2');assert.equal(state().obligations.length,2)});
 const obligations=state().obligations;
 rpc(s,'submit_v2_session_feedback',`'${obligations[0].id}','${randomUUID()}',${json({attendance:'missed',usefulness:null,clarity:null,comment:''})}`);
 check('first-feedback-resolves-only-its-session',()=>assert.equal(state().obligations.length,1));
 rpc(s,'submit_v2_session_feedback',`'${obligations[1].id}','${randomUUID()}',${json({attendance:'missed',usefulness:null,clarity:null,comment:''})}`);
 check('full-live-class-lifecycle-finishes-without-invented-attendance',()=>{assert.equal(state().obligations.length,0);assert.equal(course().sessions.length,2);assert.equal(query(`select count(*) from public.v2_session_feedback where student_id='${s}' and response->>'attendance'='missed'`),'2')});
});report.status='passed'}catch(e){report.status='failed';report.error=e.message;console.error(e);process.exitCode=1}finally{report.runnerSource=readFileSync(new URL(import.meta.url),'utf8');report.runnerSha256=createHash('sha256').update(report.runnerSource).digest('hex');writeFileSync('/tmp/ace-delivery-repair-database.json',JSON.stringify(report,null,2)+'\n')}
